DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
  -- Create template
  INSERT INTO public.evaluation_templates (program_id, name, title_en, status, status_enum, version_label, source_document_id, extraction_confidence, needs_review)
  SELECT sd.program_id, 'หลักสูตรวิศวกรรมไฟฟ้า', NULLIF('', ''), 'draft', 'draft'::assessment_status, '0.1', sd.id, 1.0, true
  FROM public.assessment_source_documents sd WHERE sd.filename = 'ผลลัพธ์การเรียนรู้ของวิชาสหกิจศึกษา-หลักสูตรวิศวกรรมไฟฟ้า-พ.ศ.2567.docx'
  RETURNING id INTO t_id;
  IF t_id IS NULL THEN RETURN; END IF;
  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 1)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้อย่างมีประสิทธิภาพ', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถวิเคราะห์และแก้ไขปัญหาทางวิศวกรรมไฟฟ้าด้วยเครื่องมือและหลักการทางคณิตศาสตร์และวิศวกรรมได้อย่างถูกต้อง', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  -- Section: ด้านทักษะ (Skills)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 2)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถวางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยี', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้อง', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถเลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการอย่างมีประสิทธิภาพ', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการ', NULLIF('', ''), NULLIF('LO7', ''), 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงาน', NULLIF('', ''), NULLIF('LO8', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความสามารถในการเรียนรู้และพัฒนาตนเองอย่างต่อเนื่องในระหว่างการปฏิบัติงานในสถานประกอบการ', NULLIF('', ''), NULLIF('LO9', ''), 'single_choice'::question_type, true, 6)
  RETURNING id INTO q_id;
  -- Section: ด้านจริยธรรม (Ethics)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านจริยธรรม (Ethics)', NULLIF('', ''), 'ethics'::domain_type, 3)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความซื่อสัตย์ ยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการ', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  -- Section: ด้านลักษณะบุคคล
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านลักษณะบุคคล', NULLIF('', ''), 'character'::domain_type, 4)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความรับผิดชอบต่อผลกระทบของงานวิศวกรรมที่ดำเนินการในสถานประกอบการ และสามารถประเมินผลกระทบต่อสังคมและสิ่งแวดล้อม', NULLIF('', ''), NULLIF('LO11', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถทำงานร่วมกับผู้อื่นในสถานประกอบการอย่างมีประสิทธิภาพ ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์ ผลการเรียนรู้ที่คาดหวัง | ผลการประเมิน (1)', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  -- Section: ด้านความรู้ (Knowledge)
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านความรู้ (Knowledge)', NULLIF('', ''), 'knowledge'::domain_type, 5)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้อย่างมีประสิทธิภาพ |   5 (ยอดเยี่ยม): ประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้อย่างครบถ้วน   4 (ดีมาก): ประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้ในระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถประยุกต์ใช้ความรู้ทางวิศวกรรมและวิทยาศาสตร์เพื่อออกแบบและพัฒนาระบบงานวิศวกรรมไฟฟ้าในสภาพแวดล้อมที่เกิดขึ้นในสถานประกอบการของการทำงานจริงได้', NULLIF('', ''), NULLIF('LO1', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถวิเคราะห์และแก้ไขปัญหาทางวิศวกรรมไฟฟ้าด้วยเครื่องมือและหลักการทางคณิตศาสตร์และวิศวกรรมได้อย่างถูกต้อง |   5 (ยอดเยี่ยม): ระบุและแก้ปัญหาที่ซับซ้อนได้อย่างครบถ้วน พร้อมเสนอแนวทางแก้ไขที่สร้างสรรค์ มีประสิทธิภาพสูง และตอบโจทย์ความต้องการของสถานประกอบการได้อย่างครบถ้วน   4 (ดีมาก): ระบุและแก้ปัญหาได้ในระดับดี พร้อมเสนอแนวทางแก้ไขที่เหมาะสม แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ระบุปัญหาและแก้ไขได้ในระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ระบุปัญหาได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถระบุหรือแก้ปัญหาได้ และไม่มีข้อเสนอแนะแนวทางแก้ไข', NULLIF('', ''), NULLIF('LO2', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้ |   5 (ยอดเยี่ยม): ประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้อย่างครบถ้วน   4 (ดีมาก): ประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้ในระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมไฟฟ้าต่อบริบทสังคม สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในสถานประกอบการได้ (2)', NULLIF('', ''), NULLIF('LO3', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
