  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULLIF('', ''), 'skills'::domain_type, 6)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถวางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยี |   5 (ยอดเยี่ยม): วางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยีได้อย่างครบถ้วน   4 (ดีมาก): วางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยีได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): วางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยีระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): วางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยีได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถวางแผน วิเคราะห์ และประเมินการลงทุนตลอดจนการบริหารงานวิศวกรรมในบริบทของสถานประกอบการ โดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงของเทคโนโลยีได้', NULLIF('', ''), NULLIF('LO4', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้อง |   5 (ยอดเยี่ยม): ออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้องได้อย่างครบถ้วน   4 (ดีมาก): ออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้องได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้องได้ระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้องได้บางส่วน แต่ไม่สามารถแก้ไขได้อย่างเหมาะสม ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถออกแบบและพัฒนากระบวนการทางวิศวกรรมในสถานประกอบการ เพื่อแก้ไขปัญหาหรือพัฒนางานตามข้อกำหนดและมาตรฐานที่เกี่ยวข้องได้', NULLIF('', ''), NULLIF('LO5', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถเลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการอย่างมีประสิทธิภาพ |   5 (ยอดเยี่ยม): เลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการอย่างถูกต้องและมีประสิทธิภาพสูงสุด   4 (ดีมาก): เลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการได้ถูกต้องแม่นยำ  แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): เลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการได้ ต้องการคำแนะนำ   2 (พอใช้): เลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการได้ บางส่วน และจำเป็นต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถเลือกใช้อุปกรณ์ เครื่องมือ และเทคโนโลยีที่เหมาะสมกับงานในสถานประกอบการได้', NULLIF('', ''), NULLIF('LO6', ''), 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการ |   5 (ยอดเยี่ยม): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการได้อย่างถูกต้องและมีประสิทธิภาพสูงสุด   4 (ดีมาก): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการได้ถูกต้องในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการได้ถูกต้องระดับพื้นฐาน แต่ข้อเสนอแนวทางแก้ไขยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ในการทำงานร่วมกับบุคลากรในสถานประกอบการได้บางส่วน แต่ยังไม่เหมาะสมกับสถานการณ์หรือมีข้อผิดพลาดที่ส่งผลต่อการทำงาน   1 (ต้องปรับปรุง): ไม่สามารถสื่อสารภาษาไทยและภาษาอังกฤษ (หรือภาษาอื่น ๆ ที่จำเป็น) ได้', NULLIF('', ''), NULLIF('LO7', ''), 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงาน |   5 (ยอดเยี่ยม): ดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงานได้อย่างถูกต้องและเหมาะสม   4 (ดีมาก): ดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงานได้ในระดับดี แม้จะมีข้อบกพร่องเล็กน้อยแต่ไม่กระทบต่อสุขภาพกายและจิตใจของตนเองในการทำงาน   3 (ดี): ดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงานได้ระดับพื้นฐาน แต่จำเป็นต้องได้รับคำแนะนำหรือแนวทางในการทำงาน   2 (พอใช้): ดูแลสุขภาพกายและจิตใจของตนเอง เพื่อให้มีความพร้อมในการรับมือกับสถานการณ์และความท้าทายในการทำงานได้บางส่วน ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถสามารถดูแลสุขภาพกายและจิตใจของตนเอง ให้มีความพร้อมการทำงานได้', NULLIF('', ''), NULLIF('LO8', ''), 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความสามารถในการเรียนรู้และพัฒนาตนเองอย่างต่อเนื่องในระหว่างการปฏิบัติงานในสถานประกอบการ |   5 (ยอดเยี่ยม): เรียนรู้และพัฒนาตนเองอย่างต่อเนื่องและสม่ำเสมอในระหว่างการปฏิบัติงานในสถานประกอบการ ค้นคว้าหาข้อมูลเพิ่มเติมด้วยตัวเอง   4 (ดีมาก): เรียนรู้และพัฒนาตนเองอย่างต่อเนื่องในระหว่างการปฏิบัติงานในสถานประกอบการในระดับดี แม้จะมีการปรับปรุงในบางส่วน   3 (ดี): เรียนรู้และพัฒนาตนเองอย่างต่อเนื่องในระหว่างการปฏิบัติงานในสถานประกอบการในระดับพื้นฐาน แต่ยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): เรียนรู้และพัฒนาตนเองอย่างต่อเนื่องในระหว่างการปฏิบัติงานในสถานประกอบการได้ และ ต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถเรียนรู้และพัฒนาตนเองในระหว่างการปฏิบัติงานในสถานประกอบการด้วยตนเอง (3)', NULLIF('', ''), NULLIF('LO9', ''), 'single_choice'::question_type, true, 6)
  RETURNING id INTO q_id;
