  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนมีความซื่อสัตย์ ยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการ |   5 (ยอดเยี่ยม): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ   มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการอย่างเคร่งครัด   4 (ดีมาก): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ         มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการได้ในระดับดี แม้จะมีข้อผิดพลาดเล็กน้อย   3 (ดี): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการได้ในระดับพื้นฐาน                    มีข้อผิดพลาดเล็กน้อยและมีข้อปรับปรุงในบางส่วน   2 (พอใช้): ซื่อสัตย์ ปฏิบัติตามกฎระเบียบ         มีความยึดมั่นในจรรยาบรรณแห่งวิชาชีพ และแสดงความกตัญญูต่อสถานประกอบการในบางโอกาส   1 (ต้องปรับปรุง): ไม่ปฏิบัติตามกฎระเบียบ และแสดงถึงความขาดความรับผิดชอบในงานอย่างชัดเจน (4)', NULLIF('', ''), NULLIF('LO10', ''), 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
