  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ผู้เรียนสามารถทำงานร่วมกับผู้อื่นในสถานประกอบการอย่างมีประสิทธิภาพ ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์ |   5 (ยอดเยี่ยม): ทำงานร่วมกับผู้อื่นในสถานประกอบการอย่างมีประสิทธิภาพ ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์   4 (ดีมาก): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้เป็นอย่างดี ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์   3 (ดี): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้ในระดับพื้นฐาน ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์ แต่ต้องได้รับคำแนะนำหรือแนวทางในการทำงาน   2 (พอใช้): ทำงานร่วมกับผู้อื่นในสถานประกอบการได้ในบางส่วน ทั้งในบทบาทผู้นำและผู้ตาม พร้อมทั้งแสดงความมีวินัยและการปรับตัวตามสถานการณ์แต่จำเป็นต้องได้รับคำแนะนำหรือแนวทางในการทำงาน   1 (ต้องปรับปรุง): ไม่สามารถทำงานร่วมกับทีมได้อย่างเหมาะสม', NULLIF('', ''), NULLIF('LO12', ''), 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
